mapper.update:
WITH credential AS (
    UPDATE auth_password_credential
    SET version = version + 1
    WHERE account_id = #{accountId}
      AND version = #{expectedVersion}
      AND status = 'ACTIVE'
      AND deleted = 0
    RETURNING id
)
UPDATE auth_password_secret
SET password_hash = #{passwordHash}
WHERE credential_id IN (SELECT id FROM credential)
